phase('Tracks')
const tracks = await parallel(TRACKS.map(t => () =>
  agent(`${GO}\n${COMMON}\n${t.prompt}`, { label: t.label, phase: 'Tracks', schema: RESULT })
    .then(r => ({ key: t.key, ...(r || { summary: 'NO RESULT' }) }))))

phase('Integration')
const integration = await agent(`${GO}
YOU ARE THE INTEGRATOR: you may edit ANY file of this build (including the frozen doubles-turn.ts and the uses-to-ko.ts turn API) for integration fixes; keep each fix minimal and note it.
${COMMON.replace('Edit ONLY files your track owns', 'The tracks are finished; you are the only editor now. (Ownership rule no longer applies to you)')}
The five tracks have finished. Their results (also in scripts/.cache/calc-audit/status-eot/build/TRACK-*.md): ${JSON.stringify(tracks)}
TASK (SPEC §8 "Integration" + ADDENDUM §8 "Integration (additions)"):
1. Resolve every needsFromOthers / needsFromIntegrator item (implement it, or say exactly why not).
2. Delete REASONS.substituteHit and its stub path.
3. Run ALL cases (556 earlier + S + R + E) through the oracle and the app side; compare.ts must report every case agreeing; the 556 earlier cases' after-the-moves fields byte-equal (allowed differences listed by script per SPEC §7 step 7). Fix the engine where they disagree (the oracle is ground truth; if you believe an oracle result is wrong, prove it with a pinned-sim probe). Then regenerate app-results/ and tests/unit/doubles-turn-showdown.test.ts with gen-tests.ts.
4. npm run check (lint, types, all unit tests) green; npm run test:battle-data:source green; golden-1v1 --check byte-equal; bench within the spec's budgets; npm run conformance:training, npm run leak:training (0 hits), npm run eval:training.
5. Server-render/script check of /calculator 2v2 (no live browser check — I will do it): Thunder Wave + Body Slam; Spore with a carried sleep counter; sand + Leftovers; Leech Seed; the end-of-turn not-estimated line; Ally Switch + Aqua Jet; Trick Choice Scarf onto a slower foe; a carried Substitute + Icicle Spear; the new controls; facts-only text.
6. Write scripts/.cache/calc-audit/status-eot/build/INTEGRATION.md with every gate's exact output line, every fix you made and anything still open.`, {
  label: 'integrator', phase: 'Integration',
  schema: { type: 'object', properties: {
    summary: { type: 'string' },
    gates: { type: 'object', properties: {
      cases: { type: 'string' }, check: { type: 'string' }, source: { type: 'string' }, golden: { type: 'string' },
      bench: { type: 'string' }, conformance: { type: 'string' }, leak: { type: 'string' }, eval: { type: 'string' },
    }, required: ['cases', 'check', 'source', 'golden', 'bench', 'conformance', 'leak', 'eval'] },
    fixes: { type: 'array', items: { type: 'string' } },
    open: { type: 'array', items: { type: 'string' } },
  }, required: ['summary', 'gates', 'fixes', 'open'] },
})

return { tracks, integration }
